/* 4 bits per pixel: 0 transparent, 1 paper, 2..9 a tone whose
 * value minus 1 is the ink level 0..8, which pvz rescales to the
 * 0..15 the engine's grey layer takes. */
static int pz_at(int id, int x, int y) {
    int i = y * PVZ_TILE + x;
    return (pz_px[id][i >> 1] >> ((i & 1) * 4)) & 15;
}
static int pz_find(const char *id) {
    for (int i = 0; i < PVZ_COUNT; i++)
        if (strcmp(pz_id[i], id) == 0) return i;
    return -1;
}
